using System.Text.Json;

namespace StickerApp.ShareServer.Friends;

public static class InviteLandingPage
{
    public static string Render(string nonce,string? appUrl)=>$$$"""
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Join a friends group · Stik-er-in</title>
<style nonce="{{{nonce}}}">:root{color-scheme:dark}[hidden]{display:none!important}body{font:17px/1.6 system-ui;background:#101114;color:#eff0f3;margin:0;padding:24px}main{max-width:420px;margin:8vh auto;padding:24px;border:1px solid #393d47;border-radius:16px;background:#191b21}a,button{display:block;box-sizing:border-box;width:100%;margin:12px 0;padding:12px;border:1px solid #5e6b68;border-radius:8px;background:#205e49;color:white;font:inherit;text-align:center;text-decoration:none}p{color:#bbc0cc}#status{font-size:14px}</style></head><body><main><h1>You’re invited</h1><p>Open Stik-er-in to review the group and confirm joining. Invites can expire or reach their join limit.</p><a id="app">Open Stik-er-in</a><button id="copy">Copy invitation</button><a id="browser" hidden>Open browser app</a><p id="status" role="status"></p><p>Don’t have the app yet? Keep this link and ask your friend how to install it. You can also paste it into Friends’ packs.</p></main>
<script nonce="{{{nonce}}}">const params=new URLSearchParams(location.hash.slice(1)),code=params.get('code')||'',server=location.origin,original=location.href;history.replaceState(null,'',location.pathname);const valid=/^[a-z0-9][a-z0-9-]{15,127}$/i.test(code);const fragment='server='+encodeURIComponent(server)+'&code='+encodeURIComponent(code);const app=document.getElementById('app');if(valid)app.href='stikerin://join#'+fragment;else{app.removeAttribute('href');document.getElementById('status').textContent='This invitation link is incomplete. Ask for a new one.'}document.getElementById('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(original);document.getElementById('status').textContent='Copied. Paste it into Friends’ packs in the app.'}catch{document.getElementById('status').textContent='Copy the original link from your chat and paste it into the app.'}});const target={{{JsonSerializer.Serialize(appUrl)}}};try{const url=new URL(target);if(valid&&(url.protocol==='https:'||url.hostname==='localhost'||url.hostname==='127.0.0.1')){url.hash=fragment;const link=document.getElementById('browser');link.href=url.href;link.hidden=false}}catch{}</script></body></html>
""";
}
